IF NOT EXISTS (SELECT name FROM sys.databases WHERE name = N'citylink_express')
BEGIN
    CREATE DATABASE [citylink_express];
END
GO

USE [citylink_express];
GO

SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

IF OBJECT_ID(N'[dbo].[incidents]', 'U') IS NOT NULL DROP TABLE [dbo].[incidents];
IF OBJECT_ID(N'[dbo].[support_requests]', 'U') IS NOT NULL DROP TABLE [dbo].[support_requests];
IF OBJECT_ID(N'[dbo].[tracking_telemetry]', 'U') IS NOT NULL DROP TABLE [dbo].[tracking_telemetry];
IF OBJECT_ID(N'[dbo].[trip_tracking]', 'U') IS NOT NULL DROP TABLE [dbo].[trip_tracking];
IF OBJECT_ID(N'[dbo].[gps_samples]', 'U') IS NOT NULL DROP TABLE [dbo].[gps_samples];
IF OBJECT_ID(N'[dbo].[notifications]', 'U') IS NOT NULL DROP TABLE [dbo].[notifications];
IF OBJECT_ID(N'[dbo].[refunds]', 'U') IS NOT NULL DROP TABLE [dbo].[refunds];
IF OBJECT_ID(N'[dbo].[payments]', 'U') IS NOT NULL DROP TABLE [dbo].[payments];
IF OBJECT_ID(N'[dbo].[bookings]', 'U') IS NOT NULL DROP TABLE [dbo].[bookings];
IF OBJECT_ID(N'[dbo].[trip_seats]', 'U') IS NOT NULL DROP TABLE [dbo].[trip_seats];
IF OBJECT_ID(N'[dbo].[trips]', 'U') IS NOT NULL DROP TABLE [dbo].[trips];
IF OBJECT_ID(N'[dbo].[route_stops]', 'U') IS NOT NULL DROP TABLE [dbo].[route_stops];
IF OBJECT_ID(N'[dbo].[stops]', 'U') IS NOT NULL DROP TABLE [dbo].[stops];
IF OBJECT_ID(N'[dbo].[routes]', 'U') IS NOT NULL DROP TABLE [dbo].[routes];
IF OBJECT_ID(N'[dbo].[staff_profiles]', 'U') IS NOT NULL DROP TABLE [dbo].[staff_profiles];
IF OBJECT_ID(N'[dbo].[seats]', 'U') IS NOT NULL DROP TABLE [dbo].[seats];
IF OBJECT_ID(N'[dbo].[buses]', 'U') IS NOT NULL DROP TABLE [dbo].[buses];
IF OBJECT_ID(N'[dbo].[challenges]', 'U') IS NOT NULL DROP TABLE [dbo].[challenges];
IF OBJECT_ID(N'[dbo].[staff]', 'U') IS NOT NULL DROP TABLE [dbo].[staff];
IF OBJECT_ID(N'[dbo].[users]', 'U') IS NOT NULL DROP TABLE [dbo].[users];
IF OBJECT_ID(N'[dbo].[resource_mutex]', 'U') IS NOT NULL DROP TABLE [dbo].[resource_mutex];
IF OBJECT_ID(N'[dbo].[system_settings]', 'U') IS NOT NULL DROP TABLE [dbo].[system_settings];
GO

CREATE TABLE [dbo].[users] (
  [id] bigint NOT NULL IDENTITY(1,1) PRIMARY KEY,
  [first_name] nvarchar(80) NOT NULL,
  [last_name] nvarchar(80) NOT NULL,
  [email] nvarchar(190) NOT NULL,
  [phone] nvarchar(24) NOT NULL,
  [password_hash] nvarchar(100) NOT NULL,
  [role] nvarchar(32) NOT NULL,
  [status] nvarchar(32) NOT NULL,
  [verified] bit NOT NULL DEFAULT 1,
  [permissions] nvarchar(500) NOT NULL DEFAULT N'',
  [token_version] int NOT NULL DEFAULT 0,
  [created_at] datetime2(6) NOT NULL DEFAULT SYSUTCDATETIME(),
  [updated_at] datetime2(6) NOT NULL DEFAULT SYSUTCDATETIME(),
  CONSTRAINT [uq_user_email] UNIQUE ([email])
);
GO

CREATE TABLE [dbo].[staff] (
  [id] bigint NOT NULL IDENTITY(1,1) PRIMARY KEY,
  [employee_id] nvarchar(40) NOT NULL,
  [first_name] nvarchar(80) NOT NULL,
  [last_name] nvarchar(80) NOT NULL,
  [email] nvarchar(190) NOT NULL,
  [phone] nvarchar(24) NOT NULL,
  [nic] nvarchar(24) NOT NULL,
  [role] nvarchar(32) NOT NULL,
  [department] nvarchar(60) NOT NULL,
  [license_number] nvarchar(60) NULL,
  [status] nvarchar(32) NOT NULL DEFAULT N'ACTIVE',
  [available] bit NOT NULL DEFAULT 1,
  [password_hash] nvarchar(100) NOT NULL,
  [permissions] nvarchar(500) NOT NULL DEFAULT N'',
  [token_version] int NOT NULL DEFAULT 0,
  [created_at] datetime2(6) NOT NULL DEFAULT SYSUTCDATETIME(),
  [updated_at] datetime2(6) NOT NULL DEFAULT SYSUTCDATETIME(),
  CONSTRAINT [uq_staff_email] UNIQUE ([email]),
  CONSTRAINT [uq_staff_employee_id] UNIQUE ([employee_id])
);
GO

CREATE TABLE [dbo].[challenges] (
  [id] bigint NOT NULL IDENTITY(1,1) PRIMARY KEY,
  [public_id] nvarchar(64) NOT NULL,
  [email] nvarchar(190) NOT NULL,
  [purpose] nvarchar(24) NOT NULL,
  [code_hash] nvarchar(100) NOT NULL,
  [expires_at] datetime2(6) NOT NULL,
  [attempts] int NOT NULL DEFAULT 0,
  [resend_after] datetime2(6) NOT NULL,
  [first_name] nvarchar(80) NULL,
  [last_name] nvarchar(80) NULL,
  [phone] nvarchar(24) NULL,
  [password_hash] nvarchar(100) NULL,
  [role] nvarchar(32) NULL,
  [used] bit NOT NULL DEFAULT 0,
  CONSTRAINT [uq_challenge_public] UNIQUE ([public_id])
);
CREATE NONCLUSTERED INDEX [ix_challenge_email] ON [dbo].[challenges] ([email], [purpose], [expires_at]);
GO

CREATE TABLE [dbo].[buses] (
  [id] bigint NOT NULL IDENTITY(1,1) PRIMARY KEY,
  [registration] nvarchar(40) NOT NULL,
  [model] nvarchar(120) NOT NULL,
  [capacity] int NOT NULL,
  [type] nvarchar(60) NOT NULL,
  [features] nvarchar(500) NOT NULL,
  [status] nvarchar(32) NOT NULL DEFAULT N'AVAILABLE',
  CONSTRAINT [uq_bus_registration] UNIQUE ([registration])
);
GO

CREATE TABLE [dbo].[seats] (
  [id] bigint NOT NULL IDENTITY(1,1) PRIMARY KEY,
  [bus_id] bigint NOT NULL,
  [number] nvarchar(12) NOT NULL,
  [seat_row] int NOT NULL,
  [column_number] int NOT NULL,
  [type] nvarchar(24) NOT NULL,
  [position] nvarchar(24) NOT NULL,
  [enabled] bit NOT NULL DEFAULT 1,
  CONSTRAINT [uq_bus_seat] UNIQUE ([bus_id], [number]),
  CONSTRAINT [fk_seats_bus] FOREIGN KEY ([bus_id]) REFERENCES [dbo].[buses]([id]) ON DELETE CASCADE
);
GO

CREATE TABLE [dbo].[staff_profiles] (
  [id] bigint NOT NULL IDENTITY(1,1) PRIMARY KEY,
  [user_id] bigint NOT NULL,
  [license_number] nvarchar(60) NULL,
  [available] bit NOT NULL DEFAULT 1,
  CONSTRAINT [uq_staff_user] UNIQUE ([user_id]),
  CONSTRAINT [fk_staff_profiles_user] FOREIGN KEY ([user_id]) REFERENCES [dbo].[users]([id])
);
GO

CREATE TABLE [dbo].[routes] (
  [id] bigint NOT NULL IDENTITY(1,1) PRIMARY KEY,
  [name] nvarchar(150) NOT NULL,
  [origin] nvarchar(80) NOT NULL,
  [destination] nvarchar(80) NOT NULL,
  [distance_km] float NOT NULL,
  [active] bit NOT NULL DEFAULT 1
);
CREATE NONCLUSTERED INDEX [ix_route_search] ON [dbo].[routes] ([origin], [destination]);
GO

CREATE TABLE [dbo].[stops] (
  [id] bigint NOT NULL IDENTITY(1,1) PRIMARY KEY,
  [name] nvarchar(120) NOT NULL,
  [latitude] float NOT NULL,
  [longitude] float NOT NULL
);
GO

CREATE TABLE [dbo].[route_stops] (
  [id] bigint NOT NULL IDENTITY(1,1) PRIMARY KEY,
  [route_id] bigint NOT NULL,
  [stop_id] bigint NOT NULL,
  [stop_order] int NOT NULL,
  [minutes_from_departure] int NOT NULL,
  CONSTRAINT [uq_route_order] UNIQUE ([route_id], [stop_order]),
  CONSTRAINT [fk_route_stops_route] FOREIGN KEY ([route_id]) REFERENCES [dbo].[routes]([id]) ON DELETE CASCADE,
  CONSTRAINT [fk_route_stops_stop] FOREIGN KEY ([stop_id]) REFERENCES [dbo].[stops]([id])
);
GO

CREATE TABLE [dbo].[trips] (
  [id] bigint NOT NULL IDENTITY(1,1) PRIMARY KEY,
  [route_id] bigint NOT NULL,
  [bus_id] bigint NULL,
  [driver_id] bigint NULL,
  [conductor_id] bigint NULL,
  [departure] datetime2(6) NOT NULL,
  [arrival] datetime2(6) NOT NULL,
  [fare] decimal(12,2) NOT NULL,
  [status] nvarchar(32) NOT NULL,
  [driver_acknowledged] bit NOT NULL DEFAULT 0,
  [conductor_acknowledged] bit NOT NULL DEFAULT 0,
  [delay_minutes] int NOT NULL DEFAULT 0,
  [gps_available] bit NOT NULL DEFAULT 1,
  [created_at] datetime2(6) NOT NULL DEFAULT SYSUTCDATETIME(),
  CONSTRAINT [fk_trips_route] FOREIGN KEY ([route_id]) REFERENCES [dbo].[routes]([id]),
  CONSTRAINT [fk_trips_bus] FOREIGN KEY ([bus_id]) REFERENCES [dbo].[buses]([id]),
  CONSTRAINT [fk_trips_driver] FOREIGN KEY ([driver_id]) REFERENCES [dbo].[users]([id]),
  CONSTRAINT [fk_trips_conductor] FOREIGN KEY ([conductor_id]) REFERENCES [dbo].[users]([id])
);
CREATE NONCLUSTERED INDEX [ix_trip_search] ON [dbo].[trips] ([departure], [status], [route_id]);
CREATE NONCLUSTERED INDEX [ix_trip_bus] ON [dbo].[trips] ([bus_id], [departure], [arrival]);
CREATE NONCLUSTERED INDEX [ix_trip_driver] ON [dbo].[trips] ([driver_id], [departure], [arrival]);
CREATE NONCLUSTERED INDEX [ix_trip_conductor] ON [dbo].[trips] ([conductor_id], [departure], [arrival]);
GO

CREATE TABLE [dbo].[trip_seats] (
  [id] bigint NOT NULL IDENTITY(1,1) PRIMARY KEY,
  [trip_id] bigint NOT NULL,
  [seat_id] bigint NOT NULL,
  [status] nvarchar(24) NOT NULL DEFAULT N'AVAILABLE',
  [held_by_id] bigint NULL,
  [hold_token] nvarchar(64) NULL,
  [expires_at] datetime2(6) NULL,
  CONSTRAINT [uq_trip_seat] UNIQUE ([trip_id], [seat_id]),
  CONSTRAINT [fk_trip_seats_trip] FOREIGN KEY ([trip_id]) REFERENCES [dbo].[trips]([id]) ON DELETE CASCADE,
  CONSTRAINT [fk_trip_seats_seat] FOREIGN KEY ([seat_id]) REFERENCES [dbo].[seats]([id]),
  CONSTRAINT [fk_trip_seats_held_by] FOREIGN KEY ([held_by_id]) REFERENCES [dbo].[users]([id])
);
CREATE UNIQUE NONCLUSTERED INDEX [uq_hold_token] ON [dbo].[trip_seats] ([hold_token]) WHERE [hold_token] IS NOT NULL;
CREATE NONCLUSTERED INDEX [ix_hold_expiry] ON [dbo].[trip_seats] ([status], [expires_at]);
GO

CREATE TABLE [dbo].[bookings] (
  [id] bigint NOT NULL IDENTITY(1,1) PRIMARY KEY,
  [passenger_id] bigint NOT NULL,
  [trip_id] bigint NOT NULL,
  [seat_id] bigint NOT NULL,
  [reference] nvarchar(40) NOT NULL,
  [passenger_name] nvarchar(160) NOT NULL,
  [passenger_phone] nvarchar(24) NOT NULL,
  [status] nvarchar(32) NOT NULL,
  [total_amount] decimal(12,2) NOT NULL,
  [pickup_stop] nvarchar(120) NULL,
  [dropoff_stop] nvarchar(120) NULL,
  [created_at] datetime2(6) NOT NULL DEFAULT SYSUTCDATETIME(),
  CONSTRAINT [uq_booking_reference] UNIQUE ([reference]),
  CONSTRAINT [fk_bookings_passenger] FOREIGN KEY ([passenger_id]) REFERENCES [dbo].[users]([id]),
  CONSTRAINT [fk_bookings_trip] FOREIGN KEY ([trip_id]) REFERENCES [dbo].[trips]([id]),
  CONSTRAINT [fk_bookings_seat] FOREIGN KEY ([seat_id]) REFERENCES [dbo].[seats]([id])
);
CREATE NONCLUSTERED INDEX [ix_booking_owner] ON [dbo].[bookings] ([passenger_id], [created_at]);
CREATE NONCLUSTERED INDEX [ix_booking_trip] ON [dbo].[bookings] ([trip_id], [status]);
GO

CREATE TABLE [dbo].[payments] (
  [id] bigint NOT NULL IDENTITY(1,1) PRIMARY KEY,
  [booking_id] bigint NOT NULL,
  [amount] decimal(12,2) NOT NULL,
  [method] nvarchar(32) NOT NULL,
  [status] nvarchar(32) NOT NULL,
  [transaction_reference] nvarchar(100) NOT NULL,
  [idempotency_key] nvarchar(80) NOT NULL,
  [refund_failure] bit NOT NULL DEFAULT 0,
  [created_at] datetime2(6) NOT NULL DEFAULT SYSUTCDATETIME(),
  CONSTRAINT [uq_payment_key] UNIQUE ([idempotency_key]),
  CONSTRAINT [fk_payments_booking] FOREIGN KEY ([booking_id]) REFERENCES [dbo].[bookings]([id]) ON DELETE CASCADE
);
CREATE NONCLUSTERED INDEX [ix_payment_booking] ON [dbo].[payments] ([booking_id]);
GO

CREATE TABLE [dbo].[refunds] (
  [id] bigint NOT NULL IDENTITY(1,1) PRIMARY KEY,
  [booking_id] bigint NOT NULL,
  [reason] nvarchar(2000) NOT NULL,
  [amount] decimal(12,2) NOT NULL,
  [status] nvarchar(32) NOT NULL,
  [reviewed_by_id] bigint NULL,
  [rejection_reason] nvarchar(2000) NULL,
  [attempts] int NOT NULL DEFAULT 0,
  [gateway_reference] nvarchar(100) NULL,
  [created_at] datetime2(6) NOT NULL DEFAULT SYSUTCDATETIME(),
  [updated_at] datetime2(6) NOT NULL DEFAULT SYSUTCDATETIME(),
  CONSTRAINT [uq_refund_booking] UNIQUE ([booking_id]),
  CONSTRAINT [fk_refunds_booking] FOREIGN KEY ([booking_id]) REFERENCES [dbo].[bookings]([id]),
  CONSTRAINT [fk_refunds_reviewed_by] FOREIGN KEY ([reviewed_by_id]) REFERENCES [dbo].[users]([id])
);
GO

CREATE TABLE [dbo].[notifications] (
  [id] bigint NOT NULL IDENTITY(1,1) PRIMARY KEY,
  [recipient_id] bigint NOT NULL,
  [type] nvarchar(40) NOT NULL,
  [title] nvarchar(160) NOT NULL,
  [message] nvarchar(2000) NOT NULL,
  [is_read] bit NOT NULL DEFAULT 0,
  [created_at] datetime2(6) NOT NULL DEFAULT SYSUTCDATETIME(),
  CONSTRAINT [fk_notifications_recipient] FOREIGN KEY ([recipient_id]) REFERENCES [dbo].[users]([id]) ON DELETE CASCADE
);
CREATE NONCLUSTERED INDEX [ix_notification_owner] ON [dbo].[notifications] ([recipient_id], [is_read], [created_at]);
GO

CREATE TABLE [dbo].[gps_samples] (
  [id] bigint NOT NULL IDENTITY(1,1) PRIMARY KEY,
  [trip_id] bigint NOT NULL,
  [latitude] float NOT NULL,
  [longitude] float NOT NULL,
  [speed] float NOT NULL,
  [progress] float NOT NULL,
  [recorded_at] datetime2(6) NOT NULL DEFAULT SYSUTCDATETIME(),
  CONSTRAINT [fk_gps_samples_trip] FOREIGN KEY ([trip_id]) REFERENCES [dbo].[trips]([id]) ON DELETE CASCADE
);
CREATE NONCLUSTERED INDEX [ix_gps_latest] ON [dbo].[gps_samples] ([trip_id], [recorded_at]);
GO

CREATE TABLE [dbo].[trip_tracking] (
  [id] bigint NOT NULL IDENTITY(1,1) PRIMARY KEY,
  [trip_id] bigint NOT NULL,
  [driver_id] bigint NULL,
  [bus_id] bigint NULL,
  [status] nvarchar(32) NOT NULL DEFAULT N'SCHEDULED',
  [is_live] bit NOT NULL DEFAULT 0,
  [started_at] datetime2(6) NULL,
  [ended_at] datetime2(6) NULL,
  [delay_minutes] int NOT NULL DEFAULT 0,
  [delay_reason] nvarchar(255) NULL,
  [approaching_stop_id] bigint NULL,
  [total_pickups] int NOT NULL DEFAULT 0,
  [total_dropoffs] int NOT NULL DEFAULT 0,
  [updated_at] datetime2(6) NOT NULL DEFAULT SYSUTCDATETIME(),
  CONSTRAINT [uq_trip_tracking_trip] UNIQUE ([trip_id]),
  CONSTRAINT [fk_trip_tracking_trip] FOREIGN KEY ([trip_id]) REFERENCES [dbo].[trips]([id]) ON DELETE CASCADE,
  CONSTRAINT [fk_trip_tracking_driver] FOREIGN KEY ([driver_id]) REFERENCES [dbo].[users]([id]),
  CONSTRAINT [fk_trip_tracking_bus] FOREIGN KEY ([bus_id]) REFERENCES [dbo].[buses]([id]),
  CONSTRAINT [fk_trip_tracking_stop] FOREIGN KEY ([approaching_stop_id]) REFERENCES [dbo].[stops]([id])
);
CREATE NONCLUSTERED INDEX [ix_trip_tracking_status] ON [dbo].[trip_tracking] ([status], [is_live]);
GO

CREATE TABLE [dbo].[tracking_telemetry] (
  [id] bigint NOT NULL IDENTITY(1,1) PRIMARY KEY,
  [tracking_id] bigint NOT NULL,
  [latitude] float NOT NULL,
  [longitude] float NOT NULL,
  [speed] float NOT NULL DEFAULT 0,
  [progress] float NOT NULL DEFAULT 0,
  [last_heartbeat] datetime2(6) NOT NULL DEFAULT SYSUTCDATETIME(),
  [created_at] datetime2(6) NOT NULL DEFAULT SYSUTCDATETIME(),
  CONSTRAINT [uq_telemetry_tracking] UNIQUE ([tracking_id]),
  CONSTRAINT [fk_telemetry_tracking] FOREIGN KEY ([tracking_id]) REFERENCES [dbo].[trip_tracking]([id]) ON DELETE CASCADE
);
GO

CREATE TABLE [dbo].[support_requests] (
  [id] bigint NOT NULL IDENTITY(1,1) PRIMARY KEY,
  [passenger_id] bigint NOT NULL,
  [category] nvarchar(24) NOT NULL,
  [subject] nvarchar(160) NOT NULL,
  [description] nvarchar(2000) NOT NULL,
  [status] nvarchar(24) NOT NULL DEFAULT N'OPEN',
  [response] nvarchar(2000) NULL,
  [created_at] datetime2(6) NOT NULL DEFAULT SYSUTCDATETIME(),
  [updated_at] datetime2(6) NOT NULL DEFAULT SYSUTCDATETIME(),
  CONSTRAINT [fk_support_passenger] FOREIGN KEY ([passenger_id]) REFERENCES [dbo].[users]([id])
);
CREATE NONCLUSTERED INDEX [ix_support_owner] ON [dbo].[support_requests] ([passenger_id], [status]);
GO

CREATE TABLE [dbo].[incidents] (
  [id] bigint NOT NULL IDENTITY(1,1) PRIMARY KEY,
  [bus_id] bigint NOT NULL,
  [reported_by_id] bigint NOT NULL,
  [type] nvarchar(60) NOT NULL,
  [description] nvarchar(2000) NOT NULL,
  [priority] nvarchar(20) NOT NULL DEFAULT N'LOW',
  [status] nvarchar(24) NOT NULL DEFAULT N'OPEN',
  [created_at] datetime2(6) NOT NULL DEFAULT SYSUTCDATETIME(),
  [resolved_at] datetime2(6) NULL,
  CONSTRAINT [fk_incidents_bus] FOREIGN KEY ([bus_id]) REFERENCES [dbo].[buses]([id]),
  CONSTRAINT [fk_incidents_reported_by] FOREIGN KEY ([reported_by_id]) REFERENCES [dbo].[users]([id])
);
CREATE NONCLUSTERED INDEX [ix_incident_bus] ON [dbo].[incidents] ([bus_id], [status]);
GO

CREATE TABLE [dbo].[resource_mutex] (
  [id] bigint NOT NULL PRIMARY KEY
);
INSERT INTO [dbo].[resource_mutex] ([id]) VALUES (1);
GO

CREATE TABLE [dbo].[system_settings] (
  [setting_key] nvarchar(80) NOT NULL PRIMARY KEY,
  [setting_value] nvarchar(max) NOT NULL,
  [description] nvarchar(255) NULL,
  [category] nvarchar(50) NULL,
  [updated_at] datetime2(6) NOT NULL DEFAULT SYSUTCDATETIME()
);
GO

