INSERT INTO [dbo].[support_requests] ([id], [passenger_id], [category], [subject], [description], [status], [response], [created_at], [updated_at]) VALUES
(1, 5, N'INQUIRY', N'Luggage allowance on Colombo-Kandy express', N'Can I bring a 25kg suitcase and a backpack?', N'RESOLVED', N'Yes, standard baggage allowance includes 1 suitcase up to 25kg and 1 carry-on backpack.', SYSUTCDATETIME(), SYSUTCDATETIME()),
(2, 8, N'BOOKING', N'Seat modification request', N'Can I switch my seat from aisle to window?', N'IN_PROGRESS', N'Our agent is processing your seat reallocation request.', SYSUTCDATETIME(), SYSUTCDATETIME()),
(3, 9, N'INQUIRY', N'Expressway pickup point query', N'Does the bus stop at Makumbura Multimodal Hub gate 3?', N'RESOLVED', N'Yes, all Southern express coaches board at Platform 2 of Makumbura.', SYSUTCDATETIME(), SYSUTCDATETIME());
GO
